  rec jsonb;
begin
  for rec in select * from jsonb_array_elements(payload)
  loop
    insert into products (
      id, kind, source_primary, nevo_code, name, category,
      name_normalized, match_key, energy_kcal_100g, protein_100g,
      carbs_100g, fat_100g, nutrients, quality_score, popularity,
      nl_relevance, is_published, data_version
    ) values (
      (rec->>0)::uuid,
      'generic',
      'nevo',
      rec->>1,
      rec->>2,
      rec->>3,
      rec->>4,
      rec->>5,
      (rec->>6)::numeric,
      (rec->>7)::numeric,
      (rec->>8)::numeric,
      (rec->>9)::numeric,
      '{}'::jsonb,
      100, 0, 100, true, 1
    )
    on conflict (id) do nothing;

    if rec->>10 is not null then
      insert into product_portions (product_id, label, grams, is_default, source)
      values ((rec->>0)::uuid, rec->>11, (rec->>10)::numeric, true, 'nevo')
      on conflict (product_id, label) do nothing;
    end if;

    if jsonb_array_length(rec->12) > 0 then
      insert into product_aliases (product_id, alias, alias_normalized, source)
      select (rec->>0)::uuid, a, lower(a), 'kalorie'
      from jsonb_array_elements_text(rec->12) a
      on conflict (product_id, alias_normalized) do nothing;
    end if;
  end loop;

  update catalog_meta
  set version = 1,
      nevo_version = '2025/9.0+catalog.1',
      product_count = (select count(*) from products),
      published_at = now()
  where id = 1;
end $$;
